Here's a complete, self-contained Account Settings screen for a React Native app (iOS + Android), built with only core `react-native` APIs — no extra dependencies required. It includes a profile row, grouped settings rows (navigation, toggle, and value variants), a sign-out action, and a Delete Account flow that requires a two-step native confirmation before firing the (caller-supplied) delete handler, with a loading/disabled state while the deletion is in flight.

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useState } from 'react';
import {
  Alert,
  ActivityIndicator,
  Image,
  Platform,
  SafeAreaView,
  ScrollView,
  StatusBar,
  StyleSheet,
  Switch,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';

/* ------------------------------------------------------------------ */
/* Types                                                              */
/* ------------------------------------------------------------------ */

export interface AccountUser {
  id: string;
  name: string;
  email: string;
  avatarUrl?: string;
}

export interface AccountSettingsScreenProps {
  user: AccountUser;
  /** Navigate to an edit-profile screen. */
  onEditProfile: () => void;
  /** Navigate to a sub-screen (notifications, privacy, etc). */
  onNavigate: (routeKey: string) => void;
  /** Toggle handlers are controlled by the parent so state survives navigation. */
  pushEnabled: boolean;
  onTogglePush: (value: boolean) => void;
  biometricsEnabled: boolean;
  onToggleBiometrics: (value: boolean) => void;
  /** Called after the user confirms sign-out. */
  onLogout: () => void;
  /**
   * Called after the user confirms account deletion twice.
   * Should return a Promise that resolves on success / rejects on failure.
   */
  onDeleteAccount: () => Promise<void>;
  appVersion?: string;
}

/* ------------------------------------------------------------------ */
/* Small building blocks                                              */
/* ------------------------------------------------------------------ */

function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '?';
  if (parts.length === 1) return parts[0]!.charAt(0).toUpperCase();
  return (parts[0]!.charAt(0) + parts[parts.length - 1]!.charAt(0)).toUpperCase();
}

function Avatar({ user, size = 56 }: { user: AccountUser; size?: number }) {
  const dimensionStyle = { width: size, height: size, borderRadius: size / 2 };
  if (user.avatarUrl) {
    return (
      <Image
        source={{ uri: user.avatarUrl }}
        style={[styles.avatarImage, dimensionStyle]}
        accessibilityLabel={`${user.name}'s avatar`}
      />
    );
  }
  return (
    <View style={[styles.avatarFallback, dimensionStyle]}>
      <Text style={styles.avatarInitials}>{getInitials(user.name)}</Text>
    </View>
  );
}

function SectionHeader({ title }: { title: string }) {
  return <Text style={styles.sectionHeader}>{title}</Text>;
}

interface BaseRowProps {
  label: string;
  subtitle?: string;
  destructive?: boolean;
  disabled?: boolean;
  testID?: string;
}

interface NavRowProps extends BaseRowProps {
  type: 'nav';
  value?: string;
  onPress: () => void;
}

interface ToggleRowProps extends BaseRowProps {
  type: 'toggle';
  value: boolean;
  onValueChange: (value: boolean) => void;
}

interface ActionRowProps extends BaseRowProps {
  type: 'action';
  onPress: () => void;
  loading?: boolean;
}

type SettingsRowProps = NavRowProps | ToggleRowProps | ActionRowProps;

function SettingsRow(props: SettingsRowProps) {
  const { label, subtitle, destructive, disabled, testID } = props;

  const labelStyle = [
    styles.rowLabel,
    destructive && styles.rowLabelDestructive,
    disabled && styles.rowLabelDisabled,
  ];

  if (props.type === 'toggle') {
    return (
      <View style={styles.row} testID={testID}>
        <View style={styles.rowTextContainer}>
          <Text style={labelStyle}>{label}</Text>
          {subtitle ? <Text style={styles.rowSubtitle}>{subtitle}</Text> : null}
        </View>
        <Switch
          value={props.value}
          onValueChange={props.onValueChange}
          disabled={disabled}
          trackColor={{ false: '#D1D5DB', true: '#34C759' }}
          thumbColor={Platform.OS === 'android' ? '#FFFFFF' : undefined}
        />
      </View>
    );
  }

  const onPress = props.type === 'nav' || props.type === 'action' ? props.onPress : undefined;
  const isLoading = props.type === 'action' && props.loading;

  return (
    <TouchableOpacity
      style={styles.row}
      onPress={onPress}
      disabled={disabled || isLoading}
      activeOpacity={0.6}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityState={{ disabled: disabled || isLoading }}
      testID={testID}
    >
      <View style={styles.rowTextContainer}>
        <Text style={labelStyle}>{label}</Text>
        {subtitle ? <Text style={styles.rowSubtitle}>{subtitle}</Text> : null}
      </View>

      {props.type === 'nav' && props.value ? (
        <Text style={styles.rowValue} numberOfLines={1}>
          {props.value}
        </Text>
      ) : null}

      {isLoading ? (
        <ActivityIndicator size="small" color={destructive ? '#FF3B30' : '#8E8E93'} />
      ) : props.type === 'nav' ? (
        <Text style={[styles.chevron, disabled && styles.rowLabelDisabled]}>›</Text>
      ) : null}
    </TouchableOpacity>
  );
}

/* ------------------------------------------------------------------ */
/* Main screen                                                         */
/* ------------------------------------------------------------------ */

export default function AccountSettingsScreen({
  user,
  onEditProfile,
  onNavigate,
  pushEnabled,
  onTogglePush,
  biometricsEnabled,
  onToggleBiometrics,
  onLogout,
  onDeleteAccount,
  appVersion,
}: AccountSettingsScreenProps) {
  const [isDeleting, setIsDeleting] = useState(false);

  const handleLogoutPress = useCallback(() => {
    Alert.alert('Log out?', 'You can log back in at any time.', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Log Out', style: 'destructive', onPress: onLogout },
    ]);
  }, [onLogout]);

  const runDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch (error) {
      setIsDeleting(false);
      Alert.alert(
        "Couldn't delete account",
        error instanceof Error ? error.message : 'Something went wrong. Please try again.',
      );
      return;
    }
    // On success the parent is expected to navigate away (e.g. to a logged-out
    // stack), so this component may unmount; no need to reset isDeleting here.
  }, [onDeleteAccount]);

  const handleDeletePress = useCallback(() => {
    if (isDeleting) return;

    Alert.alert(
      'Delete your account?',
      'This permanently removes your profile, settings, and data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Continue',
          style: 'destructive',
          onPress: () => {
            // Second, explicit confirmation for an irreversible, destructive action.
            Alert.alert(
              'Are you absolutely sure?',
              `Account "${user.email}" and all associated data will be deleted immediately.`,
              [
                { text: 'Cancel', style: 'cancel' },
                { text: 'Delete Account', style: 'destructive', onPress: runDelete },
              ],
              { cancelable: true },
            );
          },
        },
      ],
      { cancelable: true },
    );
  }, [isDeleting, runDelete, user.email]);

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar
        barStyle={Platform.OS === 'ios' ? 'dark-content' : 'default'}
        backgroundColor="#F2F2F7"
      />
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        <Text style={styles.title}>Account Settings</Text>

        {/* Profile row */}
        <TouchableOpacity
          style={styles.profileRow}
          onPress={onEditProfile}
          activeOpacity={0.7}
          accessibilityRole="button"
          accessibilityLabel={`Edit profile for ${user.name}`}
        >
          <Avatar user={user} />
          <View style={styles.profileTextContainer}>
            <Text style={styles.profileName} numberOfLines={1}>
              {user.name}
            </Text>
            <Text style={styles.profileEmail} numberOfLines={1}>
              {user.email}
            </Text>
          </View>
          <Text style={styles.chevron}>›</Text>
        </TouchableOpacity>

        {/* Account section */}
        <SectionHeader title="Account" />
        <View style={styles.card}>
          <SettingsRow
            type="nav"
            label="Edit Profile"
            onPress={onEditProfile}
            testID="row-edit-profile"
          />
          <View style={styles.divider} />
          <SettingsRow
            type="nav"
            label="Privacy"
            onPress={() => onNavigate('privacy')}
            testID="row-privacy"
          />
          <View style={styles.divider} />
          <SettingsRow
            type="nav"
            label="Linked Accounts"
            value="2 connected"
            onPress={() => onNavigate('linked-accounts')}
            testID="row-linked-accounts"
          />
        </View>

        {/* Preferences section */}
        <SectionHeader title="Preferences" />
        <View style={styles.card}>
          <SettingsRow
            type="toggle"
            label="Push Notifications"
            value={pushEnabled}
            onValueChange={onTogglePush}
            testID="row-push"
          />
          <View style={styles.divider} />
          <SettingsRow
            type="toggle"
            label={Platform.OS === 'ios' ? 'Face ID / Touch ID' : 'Biometric Unlock'}
            subtitle="Use biometrics to unlock the app"
            value={biometricsEnabled}
            onValueChange={onToggleBiometrics}
            testID="row-biometrics"
          />
        </View>

        {/* Support section */}
        <SectionHeader title="Support" />
        <View style={styles.card}>
          <SettingsRow
            type="nav"
            label="Help Center"
            onPress={() => onNavigate('help-center')}
            testID="row-help"
          />
          <View style={styles.divider} />
          <SettingsRow
            type="nav"
            label="Contact Us"
            onPress={() => onNavigate('contact')}
            testID="row-contact"
          />
          <View style={styles.divider} />
          <SettingsRow
            type="nav"
            label="Terms & Privacy Policy"
            onPress={() => onNavigate('legal')}
            testID="row-legal"
          />
        </View>

        {/* Sign out */}
        <View style={styles.card}>
          <SettingsRow
            type="action"
            label="Log Out"
            destructive
            onPress={handleLogoutPress}
            testID="row-logout"
          />
        </View>

        {/* Danger zone */}
        <SectionHeader title="Danger Zone" />
        <View style={styles.card}>
          <SettingsRow
            type="action"
            label={isDeleting ? 'Deleting Account…' : 'Delete Account'}
            subtitle="Permanently delete your account and all data"
            destructive
            disabled={isDeleting}
            loading={isDeleting}
            onPress={handleDeletePress}
            testID="row-delete-account"
          />
        </View>

        {appVersion ? <Text style={styles.footerText}>Version {appVersion}</Text> : null}
      </ScrollView>
    </SafeAreaView>
  );
}

/* ------------------------------------------------------------------ */
/* Styles                                                              */
/* ------------------------------------------------------------------ */

const CARD_BACKGROUND = '#FFFFFF';
const SCREEN_BACKGROUND = '#F2F2F7';
const BORDER_COLOR = '#E5E5EA';
const PRIMARY_TEXT = '#1C1C1E';
const SECONDARY_TEXT = '#8E8E93';
const DESTRUCTIVE = '#FF3B30';

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: SCREEN_BACKGROUND,
  },
  scrollContent: {
    padding: 16,
    paddingBottom: 40,
  },
  title: {
    fontSize: 28,
    fontWeight: '700',
    color: PRIMARY_TEXT,
    marginBottom: 16,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: CARD_BACKGROUND,
    borderRadius: 14,
    padding: 16,
    marginBottom: 24,
    ...Platform.select({
      ios: {
        shadowColor: '#000',
        shadowOpacity: 0.05,
        shadowRadius: 6,
        shadowOffset: { width: 0, height: 2 },
      },
      android: {
        elevation: 1,
      },
    }),
  },
  avatarImage: {
    backgroundColor: BORDER_COLOR,
  },
  avatarFallback: {
    backgroundColor: '#5856D6',
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    color: '#FFFFFF',
    fontSize: 20,
    fontWeight: '600',
  },
  profileTextContainer: {
    flex: 1,
    marginLeft: 14,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    color: PRIMARY_TEXT,
  },
  profileEmail: {
    fontSize: 14,
    color: SECONDARY_TEXT,
    marginTop: 2,
  },
  sectionHeader: {
    fontSize: 13,
    fontWeight: '600',
    color: SECONDARY_TEXT,
    textTransform: 'uppercase',
    letterSpacing: 0.4,
    marginBottom: 8,
    marginTop: 4,
    marginLeft: 4,
  },
  card: {
    backgroundColor: CARD_BACKGROUND,
    borderRadius: 14,
    marginBottom: 24,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 52,
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  rowTextContainer: {
    flex: 1,
    marginRight: 12,
  },
  rowLabel: {
    fontSize: 16,
    color: PRIMARY_TEXT,
  },
  rowLabelDestructive: {
    color: DESTRUCTIVE,
  },
  rowLabelDisabled: {
    opacity: 0.4,
  },
  rowSubtitle: {
    fontSize: 13,
    color: SECONDARY_TEXT,
    marginTop: 2,
  },
  rowValue: {
    fontSize: 15,
    color: SECONDARY_TEXT,
    maxWidth: 140,
  },
  chevron: {
    fontSize: 20,
    color: '#C7C7CC',
    marginLeft: 4,
  },
  divider: {
    height: 1,
    backgroundColor: BORDER_COLOR,
    marginLeft: 16,
  },
  footerText: {
    textAlign: 'center',
    fontSize: 12,
    color: SECONDARY_TEXT,
    marginTop: 8,
  },
});
```

Notes on how it's meant to be used:

- **Stateless by design**: `pushEnabled`, `biometricsEnabled`, and `user` are passed in as props rather than owned locally, so the screen stays a pure view and the parent (or your state layer) owns persistence.
- **Delete confirmation**: `handleDeletePress` chains two native `Alert.alert` dialogs (summary → explicit final confirmation naming the account email) before calling `onDeleteAccount`. This uses the built-in `Alert` API so it renders correctly as a native dialog on both iOS and Android without extra dependencies; the `destructive` button style is honored on iOS and gracefully ignored (still a normal button) on Android.
- **Async delete handling**: while `onDeleteAccount()` is pending, the row shows a spinner and disables itself; on rejection it shows an error alert and re-enables the row; on success it assumes the parent navigates away (e.g., to a logged-out stack).
- **No external deps**: avatar fallback uses initials instead of an icon library, and chevrons are plain Unicode text — drop in `react-native-vector-icons`/`expo-vector-icons` later if you want real iconography, it's not required for this to work.
- **Platform tweaks**: card shadow uses `shadowColor`/`elevation` via `Platform.select`, and `StatusBar`/`Switch` thumb color are adjusted per platform.
